.shared-card{position:relative;display:inline-block;flex:none;box-sizing:border-box;width:var(--size-length-70_0,68px);height:auto;aspect-ratio:5/7;min-width:0;min-height:0;padding:0;border:0;border-radius:var(--size-radius-9_0,8px);background:var(--color-material-card-face,#fffbed);color:var(--color-material-card-ink,#264e43);box-shadow:0 3px 0 var(--color-material-card-side,#aebcae);overflow:hidden;vertical-align:middle;}
.shared-card>.piece-art{display:block;width:100%;height:100%;aspect-ratio:5/7;}.shared-face{position:relative;box-sizing:border-box;display:grid;place-items:center;width:70px;height:98px;border:2px solid var(--color-material-card-rim,#e5e6d4);border-radius:9px;background:var(--color-material-card-face,#fffbed);color:inherit;font:800 34px/1 system-ui}
.shared-card.shared-red{color:var(--color-material-card-red,#b94f40);}.shared-card-corner{position:absolute;top:5px;left:5px;display:grid;gap:1px;text-align:center;font:800 15px/1 system-ui}.shared-card-corner small{font-size:12px}.shared-card-corner.bottom{inset:auto 5px 5px auto;transform:rotate(180deg)}
.shared-back-face{background:var(--color-material-card-back-face,#31594c);color:var(--color-material-card-back-pattern,#e8d9af);}.shared-back-face img{width:100%;height:100%;object-fit:contain;}
.shared-card:focus-visible,.shared-die:focus-visible{outline:var(--size-border-3_0,2px) solid var(--color-interaction-available,#db9a3f);outline-offset:2px;}.shared-card.is-selected{outline:var(--size-border-3_0,2px) solid var(--color-interaction-available,#db9a3f);}.shared-card.is-playable{box-shadow:0 0 0 2px #628667,0 3px 0 var(--color-material-card-side,#aebcae);}
.shared-die{display:inline-block;flex:none;box-sizing:border-box;width:var(--size-length-52_0,52px);height:auto;aspect-ratio:1;padding:0;border:0;border-radius:var(--size-radius-12_0,12px);background:transparent;color:#285040;box-shadow:0 3px 0 #b8c7ad;}.shared-die>svg{display:block!important;width:100%!important;height:100%!important;max-width:100%;aspect-ratio:1;}.shared-die:disabled,.shared-card:disabled{opacity:1;}.shared-die.held{outline:var(--size-border-3_0,2px) solid var(--color-interaction-selected,#d1a13e);outline-offset:2px;transform:translateY(-4px);}
.shared-board-tabs{display:flex;justify-content:center;gap:var(--size-space-4_0,4px);flex-wrap:wrap;}.shared-board-tabs button{min-height:var(--size-length-36_0,36px);padding:var(--size-space-5_0,4px) var(--size-space-12_0,12px);border:var(--size-border-1_0,1px) solid var(--color-border-subtle,#b6c8b5);border-radius:var(--size-radius-10_0,8px);background:var(--color-surface-raised,#e6e9dc);color:var(--color-text-primary,var(--color-material-card-back-face,#31594c));font:700 var(--size-type-12_0,12px) system-ui;}.shared-board-tabs button[aria-pressed=true]{background:var(--color-action-primary,var(--color-material-card-back-face,#31594c));color:var(--color-action-on-primary,#fff9e8);}
.shared-hint{display:block;margin:0;line-height:1.25;text-align:center;font-size:var(--size-type-11_0,10px);color:var(--color-text-secondary,#586f5d);}.shared-action-row{display:flex;align-items:center;justify-content:center;gap:var(--size-space-8_0,8px);min-height:var(--size-length-48_0,48px);}.shared-action-row button:not(.shared-die){min-height:var(--size-length-44_0,44px);border:var(--size-border-1_0,1px) solid var(--color-border-subtle,#b6c8b5);border-radius:var(--size-radius-10_0,8px);padding:var(--size-space-5_0,4px) var(--size-space-12_0,12px);background:var(--color-surface-raised,#e8eddc);color:var(--color-text-primary,var(--color-material-card-back-face,#31594c));}

.shared-face.suit-only{background:transparent;border:0;box-shadow:none}

.shared-card-crown{position:absolute;top:10px;right:5px;width:23px;height:19px}

/* Empty physical card positions share shape, surface and skin-aware suit art. */
.shared-card-slot{box-sizing:border-box;display:inline-grid;place-items:center;flex:none;width:var(--size-length-70_0,68px);height:var(--size-length-98_0,96px);aspect-ratio:5/7;min-width:0;min-height:0;padding:0;border:var(--size-border-1_0,1px) solid color-mix(in srgb,var(--color-material-card-ink,#264e43) 10%,transparent);border-radius:var(--size-radius-9_0,8px);background:var(--card-slot-face,#aeb2af);box-shadow:inset 0 1px 3px #0002;color:var(--color-material-card-ink,#264e43);}
.shared-card-slot:disabled{opacity:.55;}.shared-card-slot>.piece-art{display:block;width:100%;height:100%;pointer-events:none;}
@keyframes required-piece-flash{0%,100%{outline-color:transparent}35%,70%{outline-color:var(--ui-danger,#b94f40);background:color-mix(in srgb,var(--ui-danger,#b94f40) 18%,transparent)}}
.piece-required{outline:var(--size-border-3_0,2px) solid var(--ui-danger,#b94f40);outline-offset:-3px;animation:required-piece-flash var(--ui-duration-highlight,900ms) ease-out;opacity:1!important;}
@media(prefers-reduced-motion:reduce){.piece-required{animation:none;background:color-mix(in srgb,var(--ui-danger,#b94f40) 18%,transparent);}}

.shared-card-slot.shared-red{color:var(--color-material-card-red,#b94f40);}

/* Main physical roles share one screen-size token; artboards remain skin-owned. */
.shared-card,.shared-card-slot{width:var(--size-card,60px);height:calc(var(--size-card,60px) * 1.4);}
.shared-die{width:var(--size-die,40px);}

/* Shared page movement and the matching equal-width tab thumb. */
:root{--ui-duration-page:300ms;--ui-easing-page:cubic-bezier(.22,.61,.36,1);}
.shared-page-deck{position:relative;overflow:hidden;}
.shared-page-deck>.shared-page-panel{position:absolute;inset:0 auto auto 0;width:100%;min-width:0;transform:translateX(calc((var(--page-number,0) - var(--page-index,0))*100%));transition:transform var(--ui-duration-page) var(--ui-easing-page);}
.shared-page-deck>.shared-page-panel.is-active{position:relative;}
.shared-page-tabs{position:relative;isolation:isolate;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0;padding:4px;border:1px solid var(--line,var(--color-border-subtle));border-radius:18px;background:var(--paper,var(--color-surface-panel));}
.shared-page-tabs::before{content:"";position:absolute;inset:4px auto 4px 4px;width:calc((100% - 8px)/2);border-radius:14px;background:var(--color-surface-raised,#e3e8d8);transform:translateX(calc(var(--page-index,0)*100%));transition:transform var(--ui-duration-page) var(--ui-easing-page);pointer-events:none;z-index:-1;}
.shared-page-tabs>button,.shared-board-tabs .shared-page-tabs>button[aria-pressed=true]{min-width:0;width:100%;margin:0;border:0;background:transparent;color:var(--ink,var(--color-text-primary));border-radius:14px;white-space:normal;}
.shared-board-tabs>.shared-page-tabs{flex:1;max-width:360px;}
.reduced-motion .shared-page-panel,.reduced-motion .shared-page-tabs::before{transition:none;}
@media(prefers-reduced-motion:reduce){.shared-page-deck>.shared-page-panel,.shared-page-tabs::before{transition:none;}}

/* One raised panel, with internal rules instead of nine framed buttons. */
.tictactoe-scene .ttt-grid{--ttt-face:var(--color-surface-panel,#fff9e6);--ttt-rule:color-mix(in srgb,var(--color-border-strong,#c9bb93) 75%,var(--ttt-face));display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr));gap:0;width:calc(100% - 8px);height:calc(100% - 8px);aspect-ratio:1;margin:0 auto 8px;padding:3%;box-sizing:border-box;background:var(--ttt-face);border:0;border-radius:var(--size-radius-16_0,16px);box-shadow:0 6px 0 color-mix(in srgb,var(--ttt-face) 78%,#000),0 8px 8px #00000014;}
.tictactoe-scene .ttt-cell{display:grid;place-items:center;min-width:0;min-height:0;padding:0;aspect-ratio:1;border:0;border-radius:0;background:transparent;box-shadow:none;color:var(--color-side-green,#4b7762);overflow:clip;}
.tictactoe-scene .ttt-cell:not(:nth-child(3n)){border-right:2px solid var(--ttt-rule)}
.tictactoe-scene .ttt-cell:nth-child(-n+6){border-bottom:2px solid var(--ttt-rule)}
.tictactoe-scene .ttt-cell.cross{color:var(--color-side-red,#be6955)}
.tictactoe-scene .ttt-cell:disabled{opacity:1}
.tictactoe-scene .ttt-cell:not(:disabled):hover{background:color-mix(in srgb,var(--color-interaction-selected,#d3aa45) 12%,transparent)}
.tictactoe-scene .ttt-cell:focus-visible{outline-offset:-4px}
.tictactoe-scene .ttt-cell>span{display:grid;place-items:center;width:100%;height:100%;min-width:0;min-height:0;overflow:clip}
.tictactoe-scene .ttt-mark{display:block;width:72%;height:72%;fill:none;stroke:currentColor;stroke-width:11;stroke-linecap:round;stroke-linejoin:round}

